package com.crowdin.client.core.http.impl.json;

import org.junit.Test;
import static org.junit.Assert.*;
import java.text.SimpleDateFormat;
import com.crowdin.client.core.http.impl.json.JacksonJsonTransformer;
import java.io.IOException;
import java.util.Date;

public class JacksonJsonTransformerTest {

    @Test
    public void parseProjectJson_ProjectTest() throws IOException {
        String json = "{\"projectName\":\"test\",\"groupId\":\"123\"}";
        Project project = JacksonJsonTransformer.parse(json, Project.class);
        assertNotNull(project);
        assertEquals("test", project.getName());
        assertEquals("123", project.getGroupId());
    }

    @Test
    public void parseProjectJson_InvalidJson_ProjectTest() throws IOException {
        String json = "{\"projectName\":\"test\",\"groupId\":\"123\"}\u0000";
        assertThrows(CrowdinApiException.class, () -> JacksonJsonTransformer.parse(json, Project.class));
    }

    @Test
    public void convertLanguageTranslations_LanguageTranslationsTest() throws IOException {
        LanguageTranslations translations = new LanguageTranslations();
        translations.add("en", "hello");
        translations.add("fr", "bonjour");
        String json = JacksonJsonTransformer.convert(translations);
        assertNotNull(json);
        assertTrue(json.contains("\"en\":\"hello\""));
        assertTrue(json.contains("\"fr\":\"bonjour\""));
    }

    @Test
    public void convertLanguageTranslations_InvalidObject_LanguageTranslationsTest() throws IOException {
        assertThrows(CrowdinApiException.class, () -> JacksonJsonTransformer.convert(new Object()));
    }

    @Test
    public void convertExportOptions_ExportOptionsTest() throws IOException {
        ExportOptions options = new ExportOptions();
        options.setFormat("json");
        String json = JacksonJsonTransformer.convert(options);
        assertNotNull(json);
        assertTrue(json.contains("\"format\":\"json\""));
    }

    @Test
    public void convertExportOptions_InvalidObject_ExportOptionsTest() throws IOException {
        assertThrows(CrowdinApiException.class, () -> JacksonJsonTransformer.convert(new Object()));
    }
}

